insert into public.face_knowledge_cards
  (card_id, title, category, school, technique, observation, teacher_original, editor_summary, safety_level, auto_report, source_file, source_pages, status)
values
  ('FAC-OBS-001', '眉毛', '五官／兄弟宮相關', '沈全榮老師教材', '五官觀察', '眉頭、眉身、眉尾的方向、濃淡、整齊度、是否過眼尾、是否侵入印堂、是否有斑痕痣痘。', '教材以龍眉八要整理揚眉、退印、貼順、有彩、根根見底、過目、尾聚、居額。', '眉毛可拆成形狀、密度、方向、邊界與表面異常五類觀察。', 'high', false, 'F17 沈全榮面相十二宮位22頁0142.pdf', array[7,8,9,10], 'draft'),
  ('FAC-OBS-002', '眼睛與眼神', '五官／田宅宮、夫妻宮、疾厄宮相關', '沈全榮老師教材', '五官觀察', '左右對稱、眼神穩定度、黑白分明程度、眼瞼形態、眼袋明暗、眼周紋理。', '教材區分眼睛的形、神、氣，並以眼神與氣色作為判讀條件。', '系統只記錄可見的對稱、明暗、開合與視線穩定，不推定疾病、性格或忠誠度。', 'critical', false, 'F17 沈全榮面相十二宮位22頁0142.pdf', array[10,11,13,14,15,16], 'draft'),
  ('FAC-OBS-003', '鼻子', '五官／財帛宮、疾厄宮', '沈全榮老師教材', '五官觀察', '鼻樑直度、鼻準形態、鼻翼寬度、左右對稱、表面紋理、痣痘與氣色。', '教材將鼻子同時放入財帛宮與疾厄宮，並區分山根、年壽、鼻準、鼻翼。', '鼻部應以區段標註，避免將單一鼻形直接轉成財富或健康結論。', 'critical', false, 'F17 沈全榮面相十二宮位22頁0142.pdf', array[13,14,15,16,17], 'draft'),
  ('FAC-OBS-004', '耳朵', '五官／父母宮、疾厄宮相關', '沈全榮老師教材', '五官觀察', '耳廓、耳輪、耳垂、貼合度、左右大小、表面紋理與顏色。', '283頁教材有耳形、耳軟硬、耳長短、輪飛廓反及耳部異常等段落。', '先建立耳部結構詞典；器官、壽命或疾病說法列為內部高風險資料。', 'critical', false, 'F17面相沈老師筆記283頁繁體0142.pdf', array[20], 'draft'),
  ('FAC-OBS-005', '嘴唇與口部', '五官／子女宮、夫妻宮相關', '沈全榮老師教材', '五官觀察', '唇形、厚薄、閉合、唇線、嘴角、牙齦露出與周圍紋理。', '十二宮講義將嘴部、人中、法令與夫妻／子女相關內容連結。', '只保留口部形態與表面觀察，不轉換為生育、性功能或婚姻結論。', 'critical', false, 'F17 沈全榮面相十二宮位22頁0142.pdf', array[10,11,18,19], 'draft'),
  ('FAC-OBS-006', '印堂／命宮', '核心部位／命宮', '沈全榮老師教材', '宮位判讀', '位置、寬窄、平整度、眉毛是否侵入、明暗、斑紋痣痘痕。', '教材描述命宮位於印堂與兩眉，並列出平寬、兩眉不侵、氣色與表面異常等觀察。', '印堂卡片只記錄幾何與可見表面特徵；解讀需依流派版本引用。', 'high', false, 'F17 沈全榮面相十二宮位22頁0142.pdf', array[2,3], 'draft'),
  ('FAC-OBS-007', '山根／年壽', '核心部位／疾厄宮', '沈全榮老師教材', '宮位判讀', '鼻樑起點、寬窄、高低、直度、紋理、痣與左右對稱。', '教材以山根、年壽區分鼻部觀察，並另列流年與望診內容。', '作為影像標註區域，不直接輸出心臟、肝膽或脊椎判定。', 'critical', false, 'F17 沈全榮面相十二宮位22頁0142.pdf', array[13,14,15,16], 'draft'),
  ('FAC-OBS-008', '人中', '核心部位／子女宮、財帛相關', '沈全榮老師教材', '部位觀察', '深淺、長短、寬窄、直度、橫紋、痣痕與左右偏斜。', '教材將人中列為水星／生殖系統與流年部位，並連結子女宮與財帛段落。', '僅建立形態與紋理觀察；生殖、婦科與生育內容禁止自動引用。', 'critical', false, 'F17 沈全榮面相十二宮位22頁0142.pdf', array[10,12,18,19], 'draft'),
  ('FAC-OBS-009', '法令紋', '核心部位／夫妻宮、財帛宮相關', '沈全榮老師教材', '紋理觀察', '起點、長度、深淺、連續性、是否壓到嘴角、左右對稱與痣痕。', '教材以法令紋討論婚姻、搬遷、財帛等主題。', '可作為紋理觀察欄位；解讀需顯示流派與原文來源，禁止確定性婚姻預測。', 'high', false, 'F17 沈全榮面相十二宮位22頁0142.pdf', array[10,11,12,17,18], 'draft'),
  ('FAC-OBS-010', '地閣／下巴', '核心部位／田宅宮、子女宮', '沈全榮老師教材', '部位觀察', '下巴骨寬窄、飽滿度、尖削或內收、左右對稱、表面痣痕與氣色。', '教材將地閣與下巴連結田宅、子女與晚年段落。', '先作臉部區域與形態標註，不推定晚年財產、子女孝順或家產結果。', 'high', false, 'F17 沈全榮面相十二宮位22頁0142.pdf', array[12,13,18,19], 'draft')
